// Seeds a LOCAL rehearsal scenario (chain 31337 only).
//
// Wallet addresses are the well-known Hardhat development accounts, which are public test keys
// and must never hold real funds. Only public addresses are stored. Sepolia wallets are
// generated by a separate organizer provisioning script (later stage).
//
// Usage: npm run db:seed              create the local scenario
//        npm run db:seed -- --reset   delete the local scenario's app data and re-create it
//
// Generated login passwords are written to <repo>/organizer-secrets/ (gitignored), for the
// organizer's login cards. They are never printed to the database in plain text.
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { HDNodeWallet, Mnemonic, parseEther } from "ethers";
import pg from "pg";
import { generateCardPassword, hashPassword } from "../lib/password.ts";

const HARDHAT_MNEMONIC = "test test test test test test test test test test test junk";
const LOCAL_CHAIN_ID = 31337;
const MALICIOUS_CREATOR = "P03"; // organizer-only knowledge; change freely for rehearsals

if (process.env.NEXT_PUBLIC_CHAIN_ID !== String(LOCAL_CHAIN_ID)) {
  console.error(`seed-local only runs with NEXT_PUBLIC_CHAIN_ID=${LOCAL_CHAIN_ID}.`);
  process.exit(1);
}
const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
  console.error("DATABASE_URL is not set.");
  process.exit(1);
}
const reset = process.argv.includes("--reset");

function hardhatAddress(index: number): string {
  const mnemonic = Mnemonic.fromPhrase(HARDHAT_MNEMONIC);
  return HDNodeWallet.fromMnemonic(mnemonic, `m/44'/60'/0'/0/${index}`).address;
}

type Role = "creator" | "investor" | "mule";

// Account 0 = Exchange 1, 1–5 creators, 6–14 investors, 15 mule, 16 = Exchange 2.
const roster: { id: string; role: Role; account: number }[] = [];
for (let i = 1; i <= 15; i++) {
  const role: Role = i <= 5 ? "creator" : i <= 14 ? "investor" : "mule";
  roster.push({ id: `P${String(i).padStart(2, "0")}`, role, account: i });
}

const INSTRUCTIONS: Record<Role, string> = {
  creator: "Create your project, set a mint price, and follow the organizer's briefing for your project.",
  investor: "Browse the marketplace and mint NFTs from the projects named in your briefing.",
  mule: "Watch your wallet for incoming test ETH and forward it to Exchange 2 when instructed.",
};

const FUNDING: Record<Role, { gas: string; scenario: string }> = {
  creator: { gas: "0.05", scenario: "0" },
  investor: { gas: "0.02", scenario: "0.03" },
  mule: { gas: "0.01", scenario: "0" },
};

const client = new pg.Client({ connectionString: databaseUrl });
await client.connect();

try {
  await client.query("BEGIN");

  const existing = await client.query<{ id: number }>("SELECT id FROM scenarios WHERE chain_id = $1 AND is_active", [
    LOCAL_CHAIN_ID,
  ]);
  if (existing.rows.length > 0) {
    if (!reset) {
      throw new Error("An active local scenario already exists. Re-run with --reset to replace it.");
    }
    await client.query("DELETE FROM sessions WHERE scenario_id = $1", [existing.rows[0].id]);
    await client.query("DELETE FROM scenarios WHERE id = $1", [existing.rows[0].id]);
    console.log("deleted previous local scenario (application data only)");
  }

  const scenario = await client.query<{ id: number }>(
    `INSERT INTO scenarios (name, chain_id, is_active, exchange1_address, exchange2_address)
     VALUES ('Local rehearsal', $1, TRUE, $2, $3) RETURNING id`,
    [LOCAL_CHAIN_ID, hardhatAddress(0), hardhatAddress(16)],
  );
  const scenarioId = scenario.rows[0].id;

  const credentials: string[] = ["login,password,display_name"];

  for (const p of roster) {
    const password = generateCardPassword();
    const address = hardhatAddress(p.account);
    const displayName = `Participant ${p.id}`;
    await client.query(
      `INSERT INTO participants (id, scenario_id, display_name, role, wallet_address, password_hash)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [p.id, scenarioId, displayName, p.role, address, await hashPassword(password)],
    );
    await client.query(
      `INSERT INTO participant_private (scenario_id, participant_id, instructions, is_malicious)
       VALUES ($1, $2, $3, $4)`,
      [scenarioId, p.id, INSTRUCTIONS[p.role], p.id === MALICIOUS_CREATOR],
    );
    await client.query("INSERT INTO known_addresses (scenario_id, address, public_label) VALUES ($1, $2, $3)", [
      scenarioId,
      address,
      p.id,
    ]);
    credentials.push(`${p.id},${password},${displayName}`);
  }

  await client.query(
    `INSERT INTO known_addresses (scenario_id, address, public_label)
     VALUES ($1, $2, 'Exchange 1'), ($1, $3, 'Exchange 2')`,
    [scenarioId, hardhatAddress(0), hardhatAddress(16)],
  );

  for (const [role, amounts] of Object.entries(FUNDING)) {
    await client.query("INSERT INTO funding_plan (scenario_id, role, gas_wei, scenario_wei) VALUES ($1, $2, $3, $4)", [
      scenarioId,
      role,
      parseEther(amounts.gas).toString(),
      parseEther(amounts.scenario).toString(),
    ]);
  }

  // Organizer account is shared across scenarios; (re)set its password each seed.
  const organizerPassword = generateCardPassword(14);
  await client.query(
    `INSERT INTO organizers (username, password_hash) VALUES ('organizer', $1)
     ON CONFLICT (username) DO UPDATE SET password_hash = EXCLUDED.password_hash`,
    [await hashPassword(organizerPassword)],
  );
  await client.query(
    "DELETE FROM sessions WHERE organizer_id = (SELECT id FROM organizers WHERE username = 'organizer')",
  );
  credentials.push(`organizer,${organizerPassword},Organizer`);

  await client.query("COMMIT");

  const secretsDir = path.join(import.meta.dirname, "..", "..", "organizer-secrets");
  await mkdir(secretsDir, { recursive: true });
  const file = path.join(secretsDir, "credentials-local.csv");
  await writeFile(file, credentials.join("\n") + "\n", { mode: 0o600 });

  console.log(`seeded local scenario #${scenarioId}: 15 participants, Exchange 1/2, funding plan`);
  console.log(`login cards written to ${path.relative(process.cwd(), file)} (gitignored)`);
} catch (error) {
  await client.query("ROLLBACK");
  console.error((error as Error).message);
  process.exitCode = 1;
} finally {
  await client.end();
}
